mapper.select:
SELECT t.*,(SELECT COUNT(*) FROM the_full_order.tb_meal_plan_template_item i WHERE i.meal_plan_template_id=t.meal_plan_template_id) item_count,
       (SELECT COUNT(DISTINCT i.day_index) FROM the_full_order.tb_meal_plan_template_item i WHERE i.meal_plan_template_id=t.meal_plan_template_id) day_count
  FROM the_full_order.tb_meal_plan_template t
 WHERE 1=1
 AND t.price_tier=#{price_tier}
 AND t.meal_plan_type=#{meal_plan_type}
 AND t.active_yn='Y'
 AND t.meal_plan_template_id=#{meal_plan_template_id}
 ORDER BY t.price_tier,t.meal_plan_type,t.template_seq
